def most_common_menu_item(list_of_menuitems: list) -> str:
    """Return the most common menu item in the flattened list."""
    def flatten(nested: list) -> itertools.chain:
        for item in nested:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    flattened_items = list(flatten(list_of_menuitems))
    item_counts = Counter(flattened_items)
    most_common_item, _ = item_counts.most_common(1)[0]
    return most_common_item

