STEMMER = PorterStemmer()

def stem_and_count(content):
    words = content.split()
    if not words:
        return {}
    last_word = words[-1]
    stemmed_words = []
    for word in words[:-1]:
        cleaned = word.strip(string.punctuation).lower()
        if cleaned:
            stemmed_words.append(STEMMER.stem(cleaned))
    last_cleaned = last_word.strip(string.punctuation).lower()
    if last_cleaned:
        stemmed_words.append(last_cleaned)
    return dict(Counter(stemmed_words))

