def reverse_words(arr):
    reversed_arr = []
    for s in arr:
        words = s.split(' ')
        reversed_words = words[::-1]
        reversed_s = ' '.join(reversed_words)
        reversed_arr.append(reversed_s)
    return np.array(reversed_arr)

