import subprocess
from multiprocessing import Pool

def run_command(cmd):
    process = subprocess.Popen(cmd, shell=True, stdout=subprocess.PIPE)
    output, _ = process.communicate()
    return output

def run_commands(commands):
    if not commands:
        return []
    with Pool() as pool:
        return pool.map(run_command, commands)

