from collections import Counter
import itertools
import operator

def most_common_menu_item(list_of_menuitems):
    def flatten(nested):
        for item in nested:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item
    flattened = list(flatten(list_of_menuitems))
    counts = Counter(flattened)
    return counts.most_common(1)[0][0]

