import subprocess
from multiprocessing import Pool

def run_commands(commands):
    if not commands:
        return []
    def execute(cmd):
        return subprocess.run(cmd, shell=True, capture_output=True, check=False).stdout
    with Pool() as pool:
        return pool.map(execute, commands)

